from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        NEG = -10**30  # -infinity for max‑plus semiring

        class SegTree:
            __slots__ = ('size', 'tree')
            def __init__(self, w: List[int]):
                sz = 1 << (len(w) - 1).bit_length()
                self.size = sz
                # identity matrix for max‑plus: [[0, -inf], [-inf, 0]]
                ID = (0, NEG, NEG, 0)
                self.tree = [ID] * (2 * sz)
                # set leaves for actual vertices
                for i, wi in enumerate(w):
                    self.tree[sz + i] = (0, wi, 0, NEG)
                # build internal nodes
                for i in range(sz - 1, 0, -1):
                    self.tree[i] = self._combine(self.tree[2*i], self.tree[2*i+1])

            @staticmethod
            def _combine(A, B):
                a00, a01, a10, a11 = A
                b00, b01, b10, b11 = B
                # max‑plus matrix multiplication
                c00 = a00 + b00
                if a01 + b10 > c00:
                    c00 = a01 + b10
                c01 = a00 + b01
                if a01 + b11 > c01:
                    c01 = a01 + b11
                c10 = a10 + b00
                if a11 + b10 > c10:
                    c10 = a11 + b10
                c11 = a10 + b01
                if a11 + b11 > c11:
                    c11 = a11 + b11
                return (c00, c01, c10, c11)

            def update(self, idx: int, w: int):
                i = self.size + idx
                self.tree[i] = (0, w, 0, NEG)
                i //= 2
                while i:
                    self.tree[i] = self._combine(self.tree[2*i], self.tree[2*i+1])
                    i //= 2

            def query(self) -> int:
                root = self.tree[1]
                # first row corresponds to previous state = 0
                return root[0] if root[0] > root[1] else root[1]

        def can(X: int) -> bool:
            # minimal required visits for each cell
            need = [(X + points[i] - 1) // points[i] for i in range(n)]

            # initialise weights w[i] for final index p = 0
            w = [0] * n
            w0 = need[0] - 1
            if w0 < 0:
                w0 = 0
            w[0] = w0
            for i in range(1, n):
                w[i] = need[i]  # i > p, so no subtraction yet

            seg = SegTree(w)

            for p in range(n):
                S = seg.query()                # max‑weight independent set
                L = 1 + p + 2 * S
                if L <= m:
                    return True

                if p + 1 < n:
                    # when p increases, weight of vertex p+1 is reduced by one
                    new_w = need[p + 1] - 1
                    if new_w < 0:
                        new_w = 0
                    seg.update(p + 1, new_w)

            return False

        # binary search on the answer
        lo, hi = 0, m * max(points)   # feasible lower bound, upper bound
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])
    S = data[2].strip()
    S_int = [ord(c) - 97 for c in S]
    size = 1 << N

    # cnt[mask][i] = number of matched positions among first i characters of S
    cnt = [[0] * (N + 1) for _ in range(size)]
    for mask in range(size):
        c = 0
        for i in range(N):
            if mask >> i & 1:
                c += 1
            cnt[mask][i + 1] = c

    # transition table: trans[mask][c] = new mask after appending character c (0..25)
    trans = [[0] * 26 for _ in range(size)]
    for mask in range(size):
        for ch in range(26):
            newcnt = [0] * (N + 1)  # newcnt[0] = 0
            for i in range(1, N + 1):
                old_i = cnt[mask][i]
                # either skip the new character or keep previous value
                val = old_i
                if val < newcnt[i - 1]:
                    val = newcnt[i - 1]
                # or match S[i-1] with the new character
                if S_int[i - 1] == ch:
                    cand = cnt[mask][i - 1] + 1
                    if cand > val:
                        val = cand
                newcnt[i] = val
            new_mask = 0
            for i in range(1, N + 1):
                if newcnt[i] == newcnt[i - 1] + 1:
                    new_mask |= (1 << (i - 1))
            trans[mask][ch] = new_mask

    # DP over the length of T
    f = [0] * size
    f[0] = 1
    for _ in range(M):
        new_f = [0] * size
        for mask in range(size):
            if f[mask] == 0:
                continue
            val = f[mask]
            row = trans[mask]
            for ch in range(26):
                new_mask = row[ch]
                new_f[new_mask] = (new_f[new_mask] + val) % MOD
        f = new_f

    ans = [0] * (N + 1)
    for mask in range(size):
        k = mask.bit_count()
        ans[k] = (ans[k] + f[mask]) % MOD

    print(' '.join(str(ans[i]) for i in range(N + 1)))

